if (_dashCooldown > 0) --_dashCooldown;
if (input.Pressed(ArenaButton::Dash) && _dashSteps == 0 && _dashCooldown == 0 && LengthSquared(direction) > 0.0f) {
    _dashSteps = 12;
    _dashDirection = Normalized(direction);
}
if (_dashSteps > 0) {
    --_dashSteps;
    _player += _dashDirection * (PlayerSpeed * 3.0f * step.seconds);
    if (_dashSteps == 0) _dashCooldown = 60;
} else {
    _player += Normalized(direction) * (PlayerSpeed * step.seconds);
}
